import React, { useEffect, useState } from 'react';
import { Search, MapPin, Filter, Briefcase, Clock, DollarSign, X } from 'lucide-react';
import SEO from '../components/SEO';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useApi } from '../contexts/ApiContext';
import JobModal from '../components/JobModal';
import FilterToggleButton from '../components/FilterToggleButton';
import SkillsList from '../components/SkillsList';
import { JobWithScore } from '../types';
import CompanyLogo from '../components/CompanyLogo';
import ReactGA from 'react-ga4';
import NewsletterSubscription from '../components/NewsletterSubscription';
import { useJobsContext } from '../contexts/JobsSearchContext';
import '@fortawesome/fontawesome-free/css/all.min.css';
import AnimatedHand from '../components/AnimatedHand';
import companiesData from '../data/companies.json'; 

const Jobs = () => {
  const {
    searchQuery, setSearchQuery,
    locationFilter, setLocationFilter,
    typeFilter, setTypeFilter,
    remoteFilter, setRemoteFilter,
    scrollY, setScrollY
  } = useJobsContext();
  const { seenJobs } = useJobsContext();
  const location = useLocation();

  const allCompanies = companiesData;
  const { currentPage, setCurrentPage, jobsPerPage } = useJobsContext();

  const [uniqueLocations, setUniqueLocations] = useState<string[]>([]);
  const { jobs, skills, loading, getJobs } = useApi();
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<any | null>(null);
  const [filteredJobsWithScore, setFilteredJobsWithScore] = useState<JobWithScore[]>([]);
  const [filteredCompanies, setFilteredCompanies] = useState(allCompanies);

  const navigate = useNavigate();

  // Compute paginated slice
  const totalJobs = filteredCompanies.length;
  const totalPages = Math.ceil(totalJobs / jobsPerPage);
  const startIndex = (currentPage - 1) * jobsPerPage;
  const paginatedCompanies = filteredCompanies.slice(startIndex, startIndex + jobsPerPage);

  // Scroll to top when page changes
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: "smooth" });
  }, [currentPage]);

  // Save scroll when leaving /jobs (navigating to /job/:id)
  useEffect(() => {
    return () => {
      setScrollY(window.scrollY);
    };
  }, [setScrollY]);

  // Find job by id once jobs are available
  // useEffect(() => { }, [navigate]);

  // Sync ?search=... from the URL into searchQuery state
  useEffect(() => {
    const params = new URLSearchParams(location.search);
    if (searchQuery) {
      params.set('search', searchQuery);
    } else {
      params.delete('search');
    }
    navigate({ pathname: location.pathname, search: params.toString() }, { replace: true });
  }, [searchQuery, navigate, location.pathname]);

  // const jobs = jobsData;
  // On mount, refresh jobs if not loaded
  useEffect(() => {
    if (!jobs) { getJobs(); return; }
    // Extract unique non-empty locations safely
    const locations = Array.from(
      new Set(jobs.map(job => job.location).filter(loc => !!loc))
    );
    setUniqueLocations(locations);

    // Restore scroll when visiting /jobs
    // Use a small delay to ensure DOM has rendered
    const timeout = setTimeout(() => {
      window.scrollTo(0, scrollY);
    }, 50);

    return () => clearTimeout(timeout);
  }, [jobs, getJobs]);


  // const jobs = jobsData;
  // On mount, refresh jobs if not loaded
  // useEffect(() => {
  //   setSearchQuery( skills? skills.join(" "): "" );
  // }, [skills]);

  // useEffect(() => {
  //   setSearchQuery( searchQuery );
  // }, [searchQuery]);

  useEffect(() => {
    filtersOpen == true &&  window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [filtersOpen]);
  const alljobs = jobs || [];

  const closeJobModal = () => {
    setModalOpen(false);
    setSelectedJob(null);
  };

  useEffect(() => {
    const icon = document.getElementById('stop-shaking-after-delay');
    if (!icon) return;

    // Remove the shake class after 3 seconds
    const timeout = setTimeout(() => {
      icon.classList.remove('fa-shake');
    }, 3000);

    return () => clearTimeout(timeout);
  }, []);
  
  useEffect(() => {
    if (!jobs) return;

    // Split search query into lowercase words
    const searchTerms = (searchQuery || '')
      .toLowerCase()
      .split(/\s+/)
      .filter(Boolean);

    const filtered: JobWithScore[] = jobs
      .map(job => {
        // Count how many search terms match (title, company, tags)
        const matchCount = searchTerms.reduce((count, term) => {
        const lowerTerm = typeof term === "string" ? term.toLowerCase() : "";
        
        const inTitle =
          typeof job.title === "string"
            ? job.title.toLowerCase().includes(lowerTerm)
            : false;
        const inCompany =
          typeof job.company === "string"
            ? job.company.toLowerCase().includes(lowerTerm)
            : false;
        const inTags =
          Array.isArray(job.tags)
            ? job.tags.some(
                tag => typeof tag === "string" && tag.toLowerCase().includes(lowerTerm)
              )
            : false;

        return count + (inTitle || inCompany || inTags ? 1 : 0);
      }, 0);


        return { ...job, skillMatchCount: matchCount };
      })
      .filter(job => {
        // If there are search terms, at least one must match
        const matchesSearch = searchTerms.length === 0 || job.skillMatchCount > 0;

        // AND logic for other filters
        const matchesLocation = locationFilter === '' || job.location === locationFilter;
        const matchesType = typeFilter === '' || job.type === typeFilter;
        const matchesRemote =
          remoteFilter === '' ||
          (remoteFilter === 'remote' && job.remote) ||
          (remoteFilter === 'onsite' && !job.remote);

        return matchesSearch && matchesLocation && matchesType && matchesRemote;
      })
      // Sort by most matches first
      .sort((a, b) => b.skillMatchCount - a.skillMatchCount);

    setFilteredJobsWithScore(filtered);
    
    // filter allCompanies and find mentioned ones
    const companyNames = filtered.map(j=>j.company.toLowerCase());
    const filteredCompanies = allCompanies.filter(c=> companyNames.includes(c.name.toLowerCase()) );
    setFilteredCompanies(filteredCompanies);
    
    ReactGA.event({
      category: 'search-action',
      action: 'filter_updated-jobs',
      label: 'Search/Filter Action',
      value: filtered.length, // You could also log filteredJobsWithScore.length
      params: {
        search: searchQuery,
        location: locationFilter,
        type: typeFilter,
        remote: remoteFilter,
        resultsCount: filtered.length
      }
    });

  }, [jobs, searchQuery, locationFilter, typeFilter, remoteFilter]);

  function extractUrl(text: string): string | null {
    if (!text) return null;           // handle null/undefined
    // Regex to match http or https URL
    const urlRegex = /(https?:\/\/[^\s]+)/g;
    const match = text.match(urlRegex);
    return match ? match[0] : null;
  }

  // Pagination controls
  const PaginationControls = () => (
    <div className="flex justify-center items-center gap-2 mt-8">
      <button
        onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
        disabled={currentPage === 1}
        className="px-3 py-1 border rounded disabled:opacity-50"
      >
        ← Prev
      </button>

      <span className="text-gray-700 text-sm">
        Page {currentPage} of {totalPages}
      </span>

      <button
        onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
        disabled={currentPage === totalPages}
        className="px-3 py-1 border rounded disabled:opacity-50"
      >
        Next →
      </button>
    </div>
  );

  return (
  <>
    <SEO 
      title="Tech Jobs in Sophia Antipolis & French Riviera | PACA-Dev"
      description="Browse the latest tech job opportunities in Sophia Antipolis, Nice, Cannes, and Monaco. Find developer, data science, and tech management positions."
      keywords="sophia antipolis jobs, tech jobs nice, developer jobs cannes, remote jobs france"
    />
   
    <div className="min-h-screen bg-gray-50">
      <JobModal job={selectedJob} isOpen={modalOpen} onClose={closeJobModal}><></></JobModal>
      
      {/* Header */}
      <div className="bg-white shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
          <h1 className="text-3xl font-bold text-gray-900 mb-2">
            {skills && skills.length > 0
              ? "Skills from Your CV"
              : filteredCompanies && filteredCompanies.length > 0
                ? `Found ${filteredCompanies.length} of ${allCompanies.length}`
                : "Tech Jobs"}
          </h1>

          <p className="text-gray-600 mb-">
            {/* Filter pills */}
            {(searchQuery || '').trim() !== '' && (
              <div className="w-full mb-6">
                <div className="flex flex-wrap items-center gap-2">
                  {(searchQuery || '').split(/\s+/).map((word, index) => (
                <div
                  key={index}
                  className="flex items-center bg-blue-100 text-blue-800 rounded-full px-3 py-1 text-sm font-medium"
                >
                  <span>{word}</span>
                  <button
                    onClick={() => {
                      const words = (searchQuery || '').split(/\s+/);
                      words.splice(index, 1);
                      setSearchQuery(words.join(' '));
                    }}
                    className="ml-2 focus:outline-none"
                    aria-label={`Remove filter ${word}`}
                  >
                    <X className="h-4 w-4" />
                  </button>
                </div>
              ))}
                </div>
              </div>
            )}
          </p>

          <p className=" mt-1">
            <button
              onClick={() => document.getElementById('subscribe')?.scrollIntoView({ behavior: 'smooth' })}
              className="inline-flex gap-2 transition"
            >
              Get alerts on new job posts
              <div className="fa-sm mt-1 ">
                <i id="stop-shaking-after-delay" className="fa-solid fa-bell fa-shake"></i>
              </div>
            </button>
          </p>
         
          {skills && skills.length > 0 && <SkillsList skills={skills} />}
        </div>
      </div>


      {/* Floating filter toggle button bottom-right */}
      <div
        className="fixed bottom-5 right-5 p-3 rounded-full bg-white shadow-lg hover:bg-gray-100 focus:outline-none focus:ring-2 focus:ring-blue-500 flex items-center justify-center text-gray-600 lg:hidden z-50"
      >
        <FilterToggleButton isOpen={filtersOpen} onToggle={() => setFiltersOpen(!filtersOpen)} />
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        
        
        <div className="flex flex-col lg:flex-row gap-8">
          
          {/* Filters Sidebar */}
          <div
            id="filters-sidebar"
            className={`bg-white rounded-lg shadow-sm p-6 top-24 lg:block ${
              filtersOpen ? 'block' : 'hidden'
            } lg:w-1/4`}
            style={{ maxHeight: 'calc(100vh - 6rem)', overflowY: 'auto' }}
          >
            <h3 className="text-lg font-semibold text-gray-900 mb-4 flex items-center">
              <Filter className="h-5 w-5 mr-2" />
              Filters
            </h3>

            {/* Search */}
            <div className="mb-6">
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Search
              </label>
              <div className="relative">
                <input
                  type="text"
                  placeholder="Job title, company, skills..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full px-4 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                />
                <Search className="absolute right-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
              </div>
            </div>

            {/* Location */}
            <div className="mb-6">
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Location
              </label>
              <select
                value={locationFilter}
                onChange={(e) => setLocationFilter(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              >
                <option value="">All Locations</option>
                {/* Dynamically generate options */}
                {uniqueLocations.map((location, index) => (
                  <option key={index} value={location}>
                    {location}
                  </option>
                ))}
              </select>
            </div>

            {/* Job Type */}
            <div className="mb-6">
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Job Type
              </label>
              <select
                value={typeFilter}
                onChange={(e) => setTypeFilter(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              >
                <option value="">All Types</option>
                <option value="Full-time">Full-time</option>
                <option value="Part-time">Part-time</option>
                <option value="Contract">Contract</option>
                <option value="Internship">Internship</option>
              </select>
            </div>

            {/* Remote */}
            <div className="mb-6">
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Work Style
              </label>
              <select
                value={remoteFilter}
                onChange={(e) => setRemoteFilter(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              >
                <option value="">All</option>
                <option value="remote">Remote OK</option>
                <option value="onsite">On-site Only</option>
              </select>
            </div>

            <button
              onClick={() => {
                setSearchQuery('');
                setLocationFilter('');
                setTypeFilter('');
                setRemoteFilter('');
              }}
              className="w-full bg-gray-100 text-gray-700 px-4 py-2 rounded-md hover:bg-gray-200 transition-colors"
            >
              Clear All Filters
            </button>
          </div>
          
          
          {/* Jobs List */}
          <div className="lg:w-3/4">
            <div className="mb-6 flex justify-between items-center">
              <p className="text-gray-600">
                Showing {filteredCompanies.length} of {allCompanies.length} companies
              </p>
            </div>

            <div className="space-y-6">
              {paginatedCompanies.map(company => {
                const isSeen = seenJobs.has(company.id.toString());
                return (
                  <div
                    key={company.id}
                    className={`border rounded-xl p-4 transition ${
                      isSeen ? "opacity-70" : "opacity-100"
                    }`}
                  >
                    <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between mb-4 space-y-4 sm:space-y-0 sm:space-x-6">
                      <div className="flex items-center space-x-4 flex-shrink-0">
                        <CompanyLogo companyName={company.name}></CompanyLogo>
                      </div>

                      <div className="flex-1 min-w-0">
                        <h3 className="text-lg sm:text-xl font-semibold text-gray-900 mb-1 break-words">
                          {company.name}
                        </h3>
                      </div>

                    </div>

                    <p className="text-gray-700 mb-4 line-clamp-3 sm:line-clamp-5">
                      {company.description}
                    </p>

                    <div className="flex flex-col sm:flex-row justify-between items-center gap-2">
                      { company.website && company.website.length > 1 &&
                        // open tab to a site
                        <a
                          href={`https://${company.website}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="w-full sm:w-auto"
                        >
                          <button className="bg-blue-600 text-white px-5 py-2 rounded-md hover:bg-blue-700 transition-colors w-full sm:w-auto text-center">
                            Visit site
                          </button>
                        </a>
                      }
                    </div>
                  </div>
                );
              })}
            </div>

            {/* Pagination */}
            {totalPages > 1 && <PaginationControls />}
          </div>
            
            {filteredCompanies.length === 0 && (
              <div className="text-center py-12">
                <Briefcase className="h-16 w-16 text-gray-300 mx-auto mb-4" />
                {loading === true ? <>
                  <div className="text-center p-10">
                    <AnimatedHand />
                  </div>
                  <h3 className="text-xl font-semibold text-gray-900 mb-2">Loading</h3>
                </>:<>
                  <h3 className="text-xl font-semibold text-gray-900 mb-2">No jobs found</h3>
                </>}
                <p className="text-gray-600">Try adjusting your search criteria or check back later for new opportunities.</p>
              </div>
            )}
          </div>
        </div>

        {/* Newsletter */}
        <div id={'subscribe'} />
        <NewsletterSubscription />
      </div>
  </>
  
    
  );
};

export default Jobs;